function bool IsVersusInteractionMap()
{
    return InStr(Caps(string(Level)), "HPV_INTERACTIONS") >= 0;
}

function SpawnVersusInteractionArena()
{
    if (Role != ROLE_Authority || !IsVersusInteractionMap())
        return;
    if (VersusInteractionArena == None)
        VersusInteractionArena = Spawn(
            Class'HPVersusInteractionArena',,,
            GetVersusPickupCenter(), rot(0,0,0));
    Log("HPVersusInteractionArena spawn actor="
        $ string(VersusInteractionArena)
        $ " level=" $ string(Level));
}

